// The catalogue texts the CLI prints. messages.json is generated by
// customers/sharedenv/catalogue/build.mjs: edit catalogue.json, never the JSON.

import { readFileSync } from 'node:fs';

const { aliases, messages } = JSON.parse(
  readFileSync(new URL('./messages.json', import.meta.url), 'utf8')
);

// What these texts tell you to do cannot be done from a terminal: renewing a key, finishing a
// renewal, entering a recovery code.
const ON_THE_SITE = new Set(['WRITE_BLOCKED_DEBT_ADMIN', 'ROTATION_UNFINISHED', 'VAULT_SEALED']);

export const onTheSite = (text) => `${text} ${messages.OPEN_IN_WEB_APP}`;

export const isCatalogued = (name) => Object.hasOwn(aliases, name) || Object.hasOwn(messages, name);

// An unknown name is a failure the CLI cannot explain: it reads as SERVER_ERROR.
export function message(name, values = {}) {
  const named = Object.hasOwn(aliases, name) ? aliases[name] : name;
  const stable = Object.hasOwn(messages, named) ? named : 'SERVER_ERROR';
  const text = messages[stable].replace(/\{([^}]*)\}/g, (raw, key) => values[key] ?? raw);
  return `[${stable}] ${ON_THE_SITE.has(stable) ? onTheSite(text) : text}`;
}

export class TrustRefusal extends Error {
  constructor(code, values = {}) {
    super(message(code, values));
    this.code = code;
  }
}
